style.css:
@-moz-document domain("docs.google.com") {
body, div.docs-texteventtarget-iframe, .kix-appview, .docs-texteventtarget-iframe, .kix-canvas-tile-content {
    background: url("https://pin.it/7gk4jCPY3") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .docs-titlebar, .docs-menubar, .docs-header, .kix-appview-editor, .kix-appview, .kix-selection-overlay {
    background-color: #000000 !important;
    color: #6A89A7 !important;
    font-style: italic !important;
  }

  .docs-title-input-label-inner, .docs-title-input {
    color: #6A89A7 !important;
    font-style: italic !important;
  }

  .kix-wordhtmlgenerator-word-node {
    color: #6A89A7 !important;
    font-style: italic !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #000000;
  }

  ::-webkit-scrollbar-thumb {
    background: #6A89A7;
    border-radius: 10px;
  }

  ::selection {
    background: rgba(106, 137, 167, 0.4) !important;
  }
}
